import sys

def main():
    lines = sys.stdin.read().split('\n')
    n = int(lines[0])
    root = {}
    out = []
    for i in range(1, n + 1):
        p = lines[i].split()
        op = p[0]
        parts = [x for x in p[1].split('/') if x]
        if op == 'mkdir':
            node = root
            for part in parts:
                node = node.setdefault(part, {})
        elif op == 'write':
            node = root
            for part in parts[:-1]:
                node = node.setdefault(part, {})
            node.setdefault(parts[-1], []).append(p[2])
        elif op == 'ls':
            node = root
            for part in parts:
                node = node[part]
            if isinstance(node, list):
                out.append(parts[-1])
            elif not node:
                out.append('-')
            else:
                out.append(' '.join(k + ('/' if isinstance(node[k], dict) else '') for k in sorted(node)))
        else:
            node = root
            for part in parts:
                node = node[part]
            out.append(''.join(node))
    print('\n'.join(out))

