import sys

lines = sys.stdin.read().split('\n')
n = int(lines[0])
folders = {'/'}
files = {}

def prefixes(parts):
    return ['/' + '/'.join(parts[:i]) for i in range(1, len(parts) + 1)]

def parent(path):
    i = path.rfind('/')
    return path[:i] if i > 0 else '/'

out = []
for i in range(1, n + 1):
    p = lines[i].split()
    op, path = p[0], p[1]
    parts = [x for x in path.split('/') if x]
    if op == 'mkdir':
        for q in prefixes(parts):
            folders.add(q)
    elif op == 'write':
        for q in prefixes(parts[:-1]):
            folders.add(q)
        files[path] = files.get(path, '') + p[2]
    elif op == 'ls':
        if path in files:
            out.append(parts[-1])
        else:
            items = []
            for f in folders:
                if f != '/' and parent(f) == path:
                    items.append((f.split('/')[-1], '/'))
            for f in files:
                if parent(f) == path:
                    items.append((f.split('/')[-1], ''))
            items.sort()
            out.append(' '.join(a + b for a, b in items) if items else '-')
    else:
        out.append(files[path])
print('\n'.join(out))

