def gen(rng):
    def fmt(ops):
        return str(len(ops)) + '\n' + '\n'.join(ops)

    def build(nops, dn, fn, depth, tlen, w_mkdir=0.2, w_write=0.35, w_ls=0.3):
        folders = {'/'}
        flist = ['/']
        files = set()
        fl = []
        ops = []

        def add_prefixes(comps):
            for i in range(1, len(comps) + 1):
                q = '/' + '/'.join(comps[:i])
                if q not in folders:
                    folders.add(q)
                    flist.append(q)

        for _ in range(nops):
            r = rng.random()
            if r < w_mkdir:
                comps = ['d' + str(rng.randint(1, dn)) for _ in range(rng.randint(1, depth))]
                add_prefixes(comps)
                ops.append('mkdir /' + '/'.join(comps))
            elif r < w_mkdir + w_write or not files:
                comps = ['d' + str(rng.randint(1, dn)) for _ in range(rng.randint(0, depth - 1))]
                add_prefixes(comps)
                path = '/' + '/'.join(comps + ['f' + str(rng.randint(1, fn))])
                if path not in files:
                    files.add(path)
                    fl.append(path)
                text = ''.join(rng.choice('abcxyz019') for _ in range(rng.randint(1, tlen)))
                ops.append(f"write {path} {text}")
            elif r < w_mkdir + w_write + w_ls:
                if files and rng.random() < 0.1:
                    ops.append('ls ' + rng.choice(fl))
                else:
                    ops.append('ls ' + rng.choice(flist))
            else:
                ops.append('read ' + rng.choice(fl))
        ops.append('ls /')
        return ops

    tests = [
        fmt(['ls /']),
        fmt(['mkdir /a', 'ls /', 'ls /a']),
        fmt(['write /f1 x', 'write /f1 yz', 'read /f1', 'ls /f1', 'ls /']),
        fmt(['mkdir /docs/work', 'write /docs/notes hello', 'write /docs/notes world', 'ls /docs', 'read /docs/notes',
             'ls /', 'ls /docs/notes', 'ls /docs/work']),
        fmt(['write /a/b/c x', 'ls /a', 'ls /a/b', 'mkdir /a/z', 'ls /a']),
        fmt(['mkdir /a/b/c', 'mkdir /a/b', 'write /a/b/c1 q', 'write /a/b/c10 r', 'write /a/b/c2 s', 'ls /a/b']),
        fmt(['write /z9 1', 'write /a1 2', 'mkdir /m5', 'ls /', 'read /a1']),
    ]
    for _ in range(70):
        small = build(rng.randint(2, 14), rng.randint(1, 3), rng.randint(1, 3), rng.randint(1, 4), 3)
        # guard against the 400-character cap on small cases
        tests.append(fmt(small))
    tests.append(fmt(build(49999, 8, 30, 5, 4)))
    tests.append(fmt(build(49999, 40, 10, 3, 3)))
    tests.append(fmt(build(20000, 3, 5, 20, 3)))
    tests.append(fmt(build(40000, 3, 20, 10, 5, w_mkdir=0.1, w_write=0.5, w_ls=0.3)))
    return tests

